import{_ as o,l as s,o as e,c as n,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"SIMD 与向量","description":"","frontmatter":{"title":"SIMD 与向量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/simd-vector.md","filePath":"cs/simd-vector.md","lastUpdated":1789023840000}'),h={name:"cs/simd-vector.md"};function m(_,a,E,f,u,P){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="simd-与向量" tabindex="-1">SIMD 与向量 <a class="header-anchor" href="#simd-与向量" aria-label="Permalink to &quot;SIMD 与向量&quot;">​</a></h1><div class="epigraph"><p>同一条指令作用在一排数据上，控制流只付一次，数据级并行才不跟 ILP 抢保留站。</p><footer>—— 据 Flynn, Some Computer Organizations and Their Effectiveness, IEEE TC 1972；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/smt">上一课</a>用标签把单核 ILP 吃到窗口和 CDB 的上限。独立加法很多时，超标量仍要每条指令各占 ROB 项、各占译码带宽。<a href="/cs/cpi-amdahl">CPI 与阿姆达尔</a>已经警告：只加宽发射，串行控制部分封顶。本课不重讲保留站。缺口是：<strong>数据规则排列时，不必为每个元素取一条指令</strong>。本课只钉 SIMD/向量：一条指令、多条数据通路。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>循环 <code>for i: z[i]=x[i]+y[i]</code> 在标量 ISA 里是加载、加、存，重复 \\(n\\) 次。Tomasulo 可以把它们重叠，但指令数仍是 \\(\\Theta(n)\\)，取指与 ROB 被填满。缺口不是更聪明的唤醒，而是编码：操作码说「加」，操作数是向量寄存器或一段连续内存。</p><p>Flynn 的 SIMD 是分类名；向量机（Cray 风格）带向量长度与剥离循环。本课把它们当作同一轴：数据级并行，不把 GPU SIMT 写进主干。</p><p><span class="marginnote">SIMD 不取消局部性：连续向量 load 吃空间局部性；gather 又回到指针追逐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>增加向量寄存器，宽度 \\(W\\) 个元素。向量加：对 \\(W\\) 对元素同时（或流水）做标量加。掩码处理循环尾与条件。内存接口按块取，对齐则一次填满一条向量。</p>',9)),(e(),l(p,null,{default:r(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20OP%5B%22%E4%B8%80%E6%9D%A1%E5%90%91%E9%87%8F%E5%8A%A0%22%5D%20--%3E%20E0%5B%22%E5%85%83%E7%B4%A0%200%22%5D%0A%20%20OP%20--%3E%20E1%5B%22%E5%85%83%E7%B4%A0%201%22%5D%0A%20%20OP%20--%3E%20EW%5B%22%E5%85%83%E7%B4%A0%20W-1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>编译器把可向量化循环打成这样的指令。控制冒险仍在标量分支上；向量内部尽量无分支。本课不引入乱序向量调度的细节。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指令数下降约 \\(W\\) 倍时，取指能量和 ROB 压力下降。阿姆达尔：循环里不能向量化的部分（循环携带相关、稀疏间接）仍按标量 ILP 走。与<a href="/cs/locality-principle">局部性原理</a>合拍的是单位步长数组；链表下一课程才会成为反例。</p><p>SIMD 与超标量正交：核可以既双发射又带向量单元。结构冒险表现为向量寄存器堆端口与访存带宽。一致性仍按 cache 行，不按向量寄存器——寄存器不是共享副本。掩码让短尾循环不必退回纯标量，但仍是同一条向量指令。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把「量化」或张量核写进来，也不进入大模型栏的实现。多核把同一向量循环分到多个程序计数器，是下一课线程级并行，不是更宽的 SIMD。</p><p>后课默认：规则数组计算可以一条指令覆盖 \\(W\\) 个元素。共享内存多核仍未出场。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ILP 吃窗口；DLP 把 \\(W\\) 个元素收进一条指令。</li><li>连续布局才吃得上；不规则访问退回标量。</li><li>多核共享 cache 是下一课的缺口。</li><li>本课不把 SIMT 或张量核写进主干。</li><li>出处：Flynn, <em>IEEE TC</em>, 1972；Hennessy and Patterson, <em>CA:AQA</em> 数据级并行。</li></ul>',9))])}const S=o(h,[["render",m]]);export{I as __pageData,S as default};
